      {
        "code": "CONFOUNDING",
        "text": "Team and opponent strength are strongly correlated with both adherence and winning; without extensive fixed effects or matched designs, estimates will be biased."
      },
      {
        "code": "MEASURE_RELIABILITY",
        "text": "The suppression recommendation may be noisy or misspecified, attenuating any true effect and requiring extensive sensitivity checks."
      },
      {
        "code": "LEAKAGE_LOOKAHEAD",
        "text": "If the suppression model is trained on the same seasons or games used to evaluate adherence, information will leak from future to past, inflating apparent predictive power."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "Multiple choices in defining adherence (e.g., threshold for match, inclusion of secondary recommendations) create a researcher degree‑of‑freedom problem that can generate false positives unless pre‑registered."
      }
    ],
    "predicted_outcome": {
      "supported": 0.05,
      "rejected": 0.05,
      "untestable": 0.70,
      "artifact": 0.10,
      "uncertain": 0.10
    },
    "decision": "proceed_with_changes",
